def twentyfifth_quote_audit(sources,fresh):
 audit=quote_audit([s for s in sources if not s['key'].startswith('sh')],fresh,codes=[])
 reviews=review_stock_endpoints([s for s in sources if s['key'].startswith('sh')],fresh['fixed_prices'],CODES,['2026-07-03','2026-07-31','2026-11-19'])
 matched=sum(p['status']=='matched'for r in reviews for p in r['points'])
 conflicts=[(r['symbol'],p['date'],p['status'])for r in reviews for p in r['points']if p['status']!='matched']
 if matched!=12 or conflicts:raise ValueError('twentyfifth quote verification scope changed')
 audit.update(source_refs=[{k:v for k,v in s.items()if k!='text'}for s in sources],stock_reviews=reviews,stock_endpoint_points=matched,stock_return_windows=8,review_note='12股票成交端点和8收益窗口跨源一致；不认证其他批次冲突关闭。',boundary='保持1e-9阈值；仅同期描述，不识别公告净影响。')
 return audit
